import * as fs from 'fs';
import * as path from 'path';

export function walkMdFiles(
  dir: string,
  fileList: string[] = [],
  excludeDirs: string[] = [
    'node_modules',
    '.git',
    'dist',
    'bin',
    'obj',
    'build',
    'out',
    'target',
    'coverage',
    '.changeset',
    'scratch',
    'test-scaffold',
    'fixtures',
    'templates',
    'examples',
    '.agent',
    '.agents',
    '.claude',
    '.cursor',
    '.github',
    '.vscode',
    '.vs',
    '.idea',
  ]
): string[] {
  try {
    if (!fs.existsSync(dir)) return fileList;
    const files = fs.readdirSync(dir);
    for (const file of files) {
      const fullPath = path.join(dir, file);
      try {
        if (fs.statSync(fullPath).isDirectory()) {
          if (!excludeDirs.includes(file) && !file.startsWith('temp-') && !file.startsWith('.temp-')) {
            walkMdFiles(fullPath, fileList, excludeDirs);
          }
        } else if (file.endsWith('.md')) {
          fileList.push(fullPath);
        }
      } catch {
        // Ignore files unlinked concurrently
      }
    }
  } catch {
    // Ignore directories removed concurrently
  }
  return fileList;
}
