/**
 * AI-SDLC: Interactive Web Dashboard & Cytoscape Graph Generator
 * Compiles PDaC Graph, RTM 360° Matrix, Quality Gate metrics, and KPI telemetry into
 * a standalone, zero-infrastructure, offline-ready HTML dashboard (reports/dashboard.html).
 */

import * as fs from 'fs';
import * as path from 'path';
import { execFileSync } from 'child_process';
import yaml from 'js-yaml';
import {
  CytoscapeEdgeData,
  CytoscapeElement,
  CytoscapeNodeData,
  DashboardHistoricalKpi,
  DashboardOptions,
  DashboardResult,
  GraphNodeLayer,
  GraphNodeStatus,
  ManualsVerificationResult,
  TaskSummary,
  TraceabilityRow,
} from '../types/index.js';
import { ReleaseKpiReport } from './release-kpis.js';
import { verifyPdacGraph } from '../verifiers/pdac-graph.js';
import { verifyTraceability } from '../verifiers/traceability.js';
import { verifyQualityGate } from '../verifiers/quality-gate.js';
import { verifyTasksGovernance } from '../verifiers/governance.js';
import { verifyTestingCoverage } from '../verifiers/testing-coverage.js';
import { verifyManuals } from '../verifiers/manuals.js';
import { walkMdFiles } from '../utils/fs.js';
import { aggregatePrKpis, AuthorKpiSummary } from './pr-kpis.js';
import { getCytoscapeScript } from './cytoscape-bundle.js';
import { readCodeCoverageSummary } from './quality-report.js';

export interface GraphElementsResult {
  elements: CytoscapeElement[];
  nodesByLayer: Record<GraphNodeLayer, number>;
  conformingCount: number;
  issueCount: number;
}

/**
 * Builds the graph elements (nodes & edges) for Cytoscape.js.
 */
export function buildGraphElements(rootDir: string = process.cwd()): GraphElementsResult {
  const pdac = verifyPdacGraph({ rootDir });
  const trace = verifyTraceability({ rootDir });

  const nodeMap = new Map<string, CytoscapeNodeData>();
  const edges: CytoscapeEdgeData[] = [];
  const edgeKeySet = new Set<string>();
  const driftTargets = new Set(pdac.drifts.map((d) => d.targetId));

  function addEdge(e: CytoscapeEdgeData) {
    const key = `${e.source}->${e.target}:${e.relation}`;
    if (!edgeKeySet.has(key)) {
      edgeKeySet.add(key);
      edges.push(e);
    }
  }

  // 1. Process PDaC Baseline Nodes (Drifts)
  for (const n of pdac.drifts) {
    driftTargets.add(n.targetId);
  }

  // 2. Scan and catalog workspace artifacts (product, security, architecture, specs)
  interface ScannedArtifact {
    id: string;
    type: string;
    title: string;
    layer: GraphNodeLayer;
    filePath: string;
    content: string;
    frontmatter: Record<string, unknown>;
  }

  const NON_GRAPH_TYPES = new Set([
    'term',
    'handoff',
    'agent-handoff',
    'tasks',
    'task-plan',
    'spec-change-proposal',
    'proposal',
    'spec-design',
    'spec-change-design',
    'design',
    'delivery-spec',
    'spec',
    'pre-merge-audit-report',
    'user-design-feedback',
    'release-kpis',
    'session-telemetry',
    'license-manifest',
    'mcp-config',
    'user-manual',
    'production-manual',
    'architecture-glossary',
  ]);

  const scannedArtifactsMap = new Map<string, ScannedArtifact>();
  const archViewByBasename = new Map<string, ScannedArtifact>();
  const artifactDirs = ['product', 'architecture', 'specs', 'security'];
  for (const dirName of artifactDirs) {
    const fullDirPath = path.join(rootDir, dirName);
    if (fs.existsSync(fullDirPath)) {
        const files = walkMdFiles(fullDirPath);
        for (const f of files) {
          try {
            const fileContent = fs.readFileSync(f, 'utf-8');
            const relPath = path.relative(rootDir, f).replace(/\\/g, '/');
            if (relPath.includes('/changes/') || relPath.startsWith('changes/')) continue;

            const match = fileContent.match(/^---\r?\n([\s\S]*?)\r?\n---/);
            if (!match) continue;
            let fm: Record<string, unknown> = {};
            try {
              fm = (yaml.load(match[1]) as Record<string, unknown>) || {};
            } catch {
              continue;
            }

            const id = typeof fm.id === 'string' ? fm.id.trim() : undefined;
            if (!id) continue;

            let type = typeof fm.type === 'string' ? fm.type.trim() : '';
            if (
              NON_GRAPH_TYPES.has(type) ||
              id.startsWith('TERM-') ||
              id.startsWith('HOF-') ||
              id.startsWith('AHOF-') ||
              id.startsWith('CHG-') ||
              id.startsWith('DSG-') ||
              id.startsWith('SPEC-') ||
              id.startsWith('TSK-') ||
              id.startsWith('UDF-') ||
              id.startsWith('AUDIT-')
            ) {
              continue;
            }

            let layer: GraphNodeLayer = 'product';

            if (id.startsWith('ARCH-INTRO-') || type === 'architecture-introduction') {
              type = 'architecture-introduction';
              layer = 'product';
            } else if (id.startsWith('JRN-') || type === 'journey') {
              type = 'journey';
              layer = 'product';
            } else if (id.startsWith('ACT-THREAT-') || type === 'threat-actor') {
              type = 'threat-actor';
              layer = 'product';
            } else if (id.startsWith('ACT-') || type === 'actor') {
              type = 'actor';
              layer = 'product';
            } else if (id.startsWith('UC-') || type === 'use-case' || type === 'usecase') {
              type = 'use-case';
              layer = 'product';
            } else if (id.startsWith('BR-') || type === 'business-rule' || type === 'rule') {
              type = 'business-rule';
              layer = 'product';
            } else if (id.startsWith('ABUSE-') || type === 'abuse-case') {
              type = 'abuse-case';
              layer = 'product';
            } else if (id.startsWith('HAZ-') || type === 'hazard') {
              type = 'hazard';
              layer = 'product';
            } else if (id.startsWith('SEC-ENC-') || type === 'security-enclave') {
              type = 'security-enclave';
              layer = 'architecture';
            } else if (id.startsWith('CMP-') || type === 'component') {
              type = 'component';
              layer = 'architecture';
            } else if (id.startsWith('ADR-') || type === 'architecture-decision-record' || type === 'adr') {
              type = 'adr';
              layer = 'architecture';
            } else if (id.startsWith('SEC-REQ-') || type === 'security-requirement') {
              type = 'security-requirement';
              layer = 'requirement';
            } else if (
              id.startsWith('FR-') ||
              id.startsWith('QR-') ||
              id.startsWith('CON-') ||
              type === 'requirement' ||
              type === 'functional-requirement' ||
              type === 'quality-requirement'
            ) {
              type = 'requirement';
              layer = 'requirement';
            } else if (id.startsWith('ARCH-') || relPath.includes('architecture/')) {
              type = 'architecture';
              layer = 'architecture';
            } else {
              type = type || 'product';
              layer = 'product';
            }

            const title = typeof fm.title === 'string' ? fm.title.trim() : id;
            const content = fileContent.replace(/^---\r?\n[\s\S]*?\r?\n---/, '').trim();

            const scannedArt: ScannedArtifact = {
              id,
              type,
              title,
              layer,
              filePath: relPath,
              content,
              frontmatter: fm,
            };

            if (layer === 'architecture' && type === 'architecture') {
              archViewByBasename.set(path.basename(relPath), scannedArt);
            } else {
              scannedArtifactsMap.set(id, scannedArt);
            }
          } catch {
            // Ignore unparseable files
          }
        }
      }
    }

  // 3. Process Traceability Requirements
  for (const r of trace.rows) {
    const isOk =
      (r.productStatus === 'COMPLIANT' || r.productStatus === 'CONFORME') &&
      (r.archStatus === 'COMPLIANT' || r.archStatus === 'CONFORME') &&
      (r.testStatus === 'COMPLIANT' || r.testStatus === 'CONFORME');
    const status: GraphNodeStatus = isOk ? 'COMPLIANT' : 'ORPHAN';
    const reqType = r.id.startsWith('SEC-REQ-') ? 'security-requirement' : 'requirement';

    nodeMap.set(r.id, {
      id: r.id,
      label: r.id,
      title: r.title,
      type: reqType,
      layer: 'requirement',
      status,
      content: r.content,
      filePath: r.filePath,
      details: {
        productStatus: r.productStatus,
        archStatus: r.archStatus,
        testStatus: r.testStatus,
        hofId: r.hofId,
      },
      upstream: r.productTraces.split(',').map((s) => s.trim()).filter(Boolean),
      downstream: [
        ...r.archTraces.split(',').map((s) => s.trim()).filter(Boolean),
        ...r.testTraces.split(',').map((s) => s.trim()).filter(Boolean),
      ],
    });

    // Edges from upstream
    for (const up of r.productTraces.split(',')) {
      const u = up.trim();
      if (u && u !== 'NINGUNO' && u !== 'NONE') {
        const isAbuse = u.startsWith('ABUSE-');
        const isArchIntro = u.startsWith('ARCH-INTRO-');
        const rel = isAbuse ? 'mitigated-by' : isArchIntro ? 'defines-goal' : 'derives-from';
        addEdge({
          id: `edge-${u}-${r.id}`,
          source: u,
          target: r.id,
          label: rel,
          relation: rel,
          status,
        });
        if (!nodeMap.has(u)) {
          const upType = u.startsWith('ARCH-INTRO-')
            ? 'architecture-introduction'
            : u.startsWith('ACT-')
            ? 'actor'
            : u.startsWith('UC-')
            ? 'use-case'
            : u.startsWith('BR-')
            ? 'business-rule'
            : u.startsWith('ABUSE-')
            ? 'abuse-case'
            : 'product';
          nodeMap.set(u, {
            id: u,
            label: u,
            title: u,
            type: upType,
            layer: 'product',
            status: 'COMPLIANT',
          });
        }
      }
    }

    // Edges to architecture
    for (const arch of r.archTraces.split(',')) {
      const a = arch.trim();
      if (a && a !== 'NINGUNO' && a !== 'NONE') {
        addEdge({
          id: `edge-${r.id}-${a}`,
          source: r.id,
          target: a,
          label: 'satisfies',
          relation: 'satisfies',
          status,
        });
        if (!nodeMap.has(a)) {
          const aType = a.startsWith('CMP-') ? 'component' : a.startsWith('ADR-') ? 'adr' : a.startsWith('SEC-ENC-') ? 'security-enclave' : 'architecture';
          const viewArt = archViewByBasename.get(a);
          nodeMap.set(a, {
            id: a,
            label: a,
            title: viewArt?.title || a,
            type: aType,
            layer: 'architecture',
            status: 'COMPLIANT',
            filePath: viewArt?.filePath,
            content: viewArt?.content,
          });
        }
      }
    }

    // Edges to tests
    for (const tst of r.testTraces.split(',')) {
      const t = tst.trim();
      if (t && t !== 'NINGUNO' && t !== 'NONE') {
        const testId = t.replace(/[^a-zA-Z0-9_-]/g, '_');
        addEdge({
          id: `edge-${r.id}-${testId}`,
          source: r.id,
          target: testId,
          label: 'verified-by',
          relation: 'verified-by',
          status,
        });
        if (!nodeMap.has(testId)) {
          let testContent = undefined;
          const fullTestPath = path.isAbsolute(t) ? t : path.join(rootDir, t);
          if (fs.existsSync(fullTestPath)) {
            try {
              testContent = fs.readFileSync(fullTestPath, 'utf-8');
            } catch {}
          }
          nodeMap.set(testId, {
            id: testId,
            label: path.basename(t),
            title: t,
            type: t.endsWith('.feature') ? 'bdd-feature' : 'code-test',
            layer: 'test',
            status: 'COMPLIANT',
            filePath: t,
            content: testContent ? '```' + (t.endsWith('.feature') ? 'gherkin' : 'typescript') + '\n' + testContent.substring(0, 1500) + (testContent.length > 1500 ? '\n... (truncated)' : '') + '\n```' : undefined,
          });
        }
      }
    }
  }

  // 4. Register all scanned artifacts into nodeMap and enrich existing ones
  for (const art of scannedArtifactsMap.values()) {
    if (!nodeMap.has(art.id)) {
      nodeMap.set(art.id, {
        id: art.id,
        label: art.id,
        title: art.title,
        type: art.type,
        layer: art.layer,
        status: 'COMPLIANT',
        filePath: art.filePath,
        content: art.content,
      });
    } else {
      const n = nodeMap.get(art.id)!;
      if (!n.filePath) n.filePath = art.filePath;
      if ((!n.title || n.title === n.id) && art.title) n.title = art.title;
      if (!n.content) n.content = art.content;
      if (art.type && (!n.type || n.type === 'product' || n.type === 'architecture' || n.type === 'usecase' || n.type === 'rule')) {
        n.type = art.type;
      }
    }
  }

  // 5. Connect product graph relationships: Vision (ARCH-INTRO-*), Journeys, Actors, Use Cases, Business Rules, Abuse Cases
  for (const art of scannedArtifactsMap.values()) {
    const fm = art.frontmatter;

    if (art.type === 'architecture-introduction') {
      // Cites Product Actors (identifies)
      const citedActors = Array.isArray(fm['cites-product-actors']) ? fm['cites-product-actors'] : [];
      for (const actId of citedActors) {
        if (typeof actId === 'string' && actId.trim()) {
          const a = actId.trim();
          if (!nodeMap.has(a)) {
            nodeMap.set(a, {
              id: a,
              label: a,
              title: a,
              type: 'actor',
              layer: 'product',
              status: 'COMPLIANT',
            });
          }
          addEdge({
            id: `edge-${art.id}-${a}`,
            source: art.id,
            target: a,
            label: 'identifies',
            relation: 'identifies',
            status: 'COMPLIANT',
          });
        }
      }

      // Cites Use Cases (envisions)
      const citedUcs = Array.isArray(fm['cites-use-cases']) ? fm['cites-use-cases'] : [];
      for (const ucId of citedUcs) {
        if (typeof ucId === 'string' && ucId.trim()) {
          const u = ucId.trim();
          if (!nodeMap.has(u)) {
            nodeMap.set(u, {
              id: u,
              label: u,
              title: u,
              type: 'use-case',
              layer: 'product',
              status: 'COMPLIANT',
            });
          }
          addEdge({
            id: `edge-${art.id}-${u}`,
            source: art.id,
            target: u,
            label: 'envisions',
            relation: 'envisions',
            status: 'COMPLIANT',
          });
        }
      }

      // Cites Quality Goals (defines-goal)
      const citedGoals = Array.isArray(fm['cites-quality-goals']) ? fm['cites-quality-goals'] : [];
      for (const qrId of citedGoals) {
        if (typeof qrId === 'string' && qrId.trim()) {
          const q = qrId.trim();
          if (!nodeMap.has(q)) {
            nodeMap.set(q, {
              id: q,
              label: q,
              title: q,
              type: q.startsWith('SEC-REQ-') ? 'security-requirement' : 'requirement',
              layer: 'requirement',
              status: 'COMPLIANT',
            });
          }
          addEdge({
            id: `edge-${art.id}-${q}`,
            source: art.id,
            target: q,
            label: 'defines-goal',
            relation: 'defines-goal',
            status: 'COMPLIANT',
          });
        }
      }
    } else if (art.type === 'journey') {
      // Persona / Actor
      const persona = typeof fm.persona === 'string' ? fm.persona : (typeof fm.actor === 'string' ? fm.actor : undefined);
      if (persona) {
        if (!nodeMap.has(persona)) {
          nodeMap.set(persona, {
            id: persona,
            label: persona,
            title: persona,
            type: 'actor',
            layer: 'product',
            status: 'COMPLIANT',
          });
        }
        addEdge({
          id: `edge-${persona}-${art.id}`,
          source: persona,
          target: art.id,
          label: 'pursues',
          relation: 'pursues',
          status: 'COMPLIANT',
        });
      }

      // Related Use Cases
      const relatedUcs = Array.isArray(fm['related-use-cases']) ? fm['related-use-cases'] : (Array.isArray(fm['use-cases']) ? fm['use-cases'] : []);
      for (const ucId of relatedUcs) {
        if (typeof ucId === 'string' && ucId.trim()) {
          const u = ucId.trim();
          if (!nodeMap.has(u)) {
            nodeMap.set(u, {
              id: u,
              label: u,
              title: u,
              type: 'use-case',
              layer: 'product',
              status: 'COMPLIANT',
            });
          }
          addEdge({
            id: `edge-${art.id}-${u}`,
            source: art.id,
            target: u,
            label: 'decomposes-into',
            relation: 'decomposes-into',
            status: 'COMPLIANT',
          });
        }
      }
    } else if (art.type === 'use-case') {
      // Primary Actor
      const primaryActor = typeof fm['primary-actor'] === 'string' ? fm['primary-actor'] : (typeof fm.actor === 'string' ? fm.actor : undefined);
      if (primaryActor) {
        if (!nodeMap.has(primaryActor)) {
          nodeMap.set(primaryActor, {
            id: primaryActor,
            label: primaryActor,
            title: primaryActor,
            type: 'actor',
            layer: 'product',
            status: 'COMPLIANT',
          });
        }
        addEdge({
          id: `edge-${primaryActor}-${art.id}`,
          source: primaryActor,
          target: art.id,
          label: 'initiates',
          relation: 'initiates',
          status: 'COMPLIANT',
        });
      }

      // Supporting / Secondary Actors
      const supportingActors = Array.isArray(fm['supporting-actors'])
        ? fm['supporting-actors']
        : Array.isArray(fm['secondary-actors'])
        ? fm['secondary-actors']
        : [];
      for (const actorId of supportingActors) {
        if (typeof actorId === 'string' && actorId.trim()) {
          const a = actorId.trim();
          if (!nodeMap.has(a)) {
            nodeMap.set(a, {
              id: a,
              label: a,
              title: a,
              type: 'actor',
              layer: 'product',
              status: 'COMPLIANT',
            });
          }
          addEdge({
            id: `edge-${a}-${art.id}`,
            source: a,
            target: art.id,
            label: 'initiates',
            relation: 'initiates',
            status: 'COMPLIANT',
          });
        }
      }

      // Governed By (Business Rules)
      const governedBy = Array.isArray(fm['governed-by'])
        ? fm['governed-by']
        : Array.isArray(fm['business-rules'])
        ? fm['business-rules']
        : [];
      for (const ruleId of governedBy) {
        if (typeof ruleId === 'string' && ruleId.trim()) {
          const r = ruleId.trim();
          if (!nodeMap.has(r)) {
            nodeMap.set(r, {
              id: r,
              label: r,
              title: r,
              type: 'business-rule',
              layer: 'product',
              status: 'COMPLIANT',
            });
          }
          addEdge({
            id: `edge-${r}-${art.id}`,
            source: r,
            target: art.id,
            label: 'governs',
            relation: 'governs',
            status: 'COMPLIANT',
          });
        }
      }
    } else if (art.type === 'business-rule') {
      const governsTargets = Array.isArray(fm['governs'])
        ? fm['governs']
        : Array.isArray(fm['applies-to'])
        ? fm['applies-to']
        : typeof fm['governs'] === 'string'
        ? [fm['governs']]
        : [];
      for (const tgt of governsTargets) {
        if (typeof tgt === 'string' && tgt.trim()) {
          const t = tgt.trim();
          addEdge({
            id: `edge-${art.id}-${t}`,
            source: art.id,
            target: t,
            label: 'governs',
            relation: 'governs',
            status: 'COMPLIANT',
          });
        }
      }
    } else if (art.type === 'abuse-case') {
      // Threat Actor
      const threatActor =
        typeof fm['primary-threat-actor'] === 'string'
          ? fm['primary-threat-actor']
          : typeof fm['threat-actor'] === 'string'
          ? fm['threat-actor']
          : typeof fm.actor === 'string'
          ? fm.actor
          : undefined;
      if (threatActor) {
        if (!nodeMap.has(threatActor)) {
          nodeMap.set(threatActor, {
            id: threatActor,
            label: threatActor,
            title: threatActor,
            type: 'threat-actor',
            layer: 'product',
            status: 'COMPLIANT',
          });
        }
        addEdge({
          id: `edge-${threatActor}-${art.id}`,
          source: threatActor,
          target: art.id,
          label: 'threatens',
          relation: 'threatens',
          status: 'COMPLIANT',
        });
      }

      // Secondary Threat Actors
      const secondaryThreatActors = Array.isArray(fm['secondary-actors'])
        ? fm['secondary-actors']
        : Array.isArray(fm['supporting-actors'])
        ? fm['supporting-actors']
        : [];
      for (const secActor of secondaryThreatActors) {
        if (typeof secActor === 'string' && secActor.trim()) {
          const sa = secActor.trim();
          if (!nodeMap.has(sa)) {
            nodeMap.set(sa, {
              id: sa,
              label: sa,
              title: sa,
              type: sa.startsWith('ACT-THREAT-') ? 'threat-actor' : 'actor',
              layer: 'product',
              status: 'COMPLIANT',
            });
          }
          addEdge({
            id: `edge-${sa}-${art.id}`,
            source: sa,
            target: art.id,
            label: 'threatens',
            relation: 'threatens',
            status: 'COMPLIANT',
          });
        }
      }

      // Targets Use Cases
      const rawTargets = Array.isArray(fm['targets-use-case'])
        ? fm['targets-use-case']
        : typeof fm['targets-use-case'] === 'string'
        ? [fm['targets-use-case']]
        : Array.isArray(fm['targets-use-cases'])
        ? fm['targets-use-cases']
        : Array.isArray(fm['targets'])
        ? fm['targets']
        : [];
      for (const tgt of rawTargets) {
        if (typeof tgt === 'string' && tgt.trim()) {
          const t = tgt.trim();
          if (nodeMap.has(t)) {
            addEdge({
              id: `edge-${art.id}-${t}`,
              source: art.id,
              target: t,
              label: 'targets',
              relation: 'targets',
              status: 'COMPLIANT',
            });
          }
        }
      }

      // Mitigated By (Security Requirements)
      const mitigatedBy = Array.isArray(fm['mitigated-by'])
        ? fm['mitigated-by']
        : typeof fm['mitigated-by'] === 'string'
        ? [fm['mitigated-by']]
        : [];
      for (const secReq of mitigatedBy) {
        if (typeof secReq === 'string' && secReq.trim()) {
          const s = secReq.trim();
          if (!nodeMap.has(s)) {
            nodeMap.set(s, {
              id: s,
              label: s,
              title: s,
              type: s.startsWith('SEC-REQ-') ? 'security-requirement' : 'requirement',
              layer: 'requirement',
              status: 'COMPLIANT',
            });
          }
          addEdge({
            id: `edge-${art.id}-${s}`,
            source: art.id,
            target: s,
            label: 'mitigated-by',
            relation: 'mitigated-by',
            status: 'COMPLIANT',
          });
        }
      }
    } else if (art.type === 'requirement' || art.type === 'security-requirement') {
      // Mitigates Abuse Cases
      const mitigates = Array.isArray(fm['mitigates-abuse-case']) ? fm['mitigates-abuse-case'] : (typeof fm['mitigates-abuse-case'] === 'string' ? [fm['mitigates-abuse-case']] : []);
      for (const abuseId of mitigates) {
        if (typeof abuseId === 'string' && abuseId.trim()) {
          const ab = abuseId.trim();
          if (!nodeMap.has(ab)) {
            nodeMap.set(ab, {
              id: ab,
              label: ab,
              title: ab,
              type: 'abuse-case',
              layer: 'product',
              status: 'COMPLIANT',
            });
          }
          addEdge({
            id: `edge-${ab}-${art.id}`,
            source: ab,
            target: art.id,
            label: 'mitigated-by',
            relation: 'mitigated-by',
            status: 'COMPLIANT',
          });
        }
      }
    } else if (art.type === 'adr') {
      // Affects Components (from schemas/architecture/adr.schema.json)
      const affectedComponents = Array.isArray(fm['affects-components'])
        ? fm['affects-components']
        : typeof fm['affects-components'] === 'string'
        ? [fm['affects-components']]
        : [];
      for (const cmpId of affectedComponents) {
        if (typeof cmpId === 'string' && cmpId.trim()) {
          const c = cmpId.trim();
          if (nodeMap.has(c)) {
            addEdge({
              id: `edge-${art.id}-${c}`,
              source: art.id,
              target: c,
              label: 'governs',
              relation: 'governs',
              status: 'COMPLIANT',
            });
          }
        }
      }
    } else if (art.type === 'security-enclave') {
      // Enforced By Security Requirements (from schemas/security/enclave.schema.json)
      const enforcedBy = Array.isArray(fm['enforced-by'])
        ? fm['enforced-by']
        : typeof fm['enforced-by'] === 'string'
        ? [fm['enforced-by']]
        : [];
      for (const secReq of enforcedBy) {
        if (typeof secReq === 'string' && secReq.trim()) {
          const s = secReq.trim();
          if (nodeMap.has(s)) {
            addEdge({
              id: `edge-${s}-${art.id}`,
              source: s,
              target: art.id,
              label: 'satisfies',
              relation: 'satisfies',
              status: 'COMPLIANT',
            });
          }
        }
      }
    }
  }

  // 6. Update status for nodes with cryptographic drifts
  for (const [id, node] of nodeMap.entries()) {
    if (driftTargets.has(id)) {
      node.status = 'DRIFT';
    }
  }

  // 7. Populate bidirectional upstream and downstream traces for all nodes
  for (const e of edges) {
    const srcNode = nodeMap.get(e.source);
    const tgtNode = nodeMap.get(e.target);
    if (srcNode) {
      srcNode.downstream = srcNode.downstream || [];
      if (!srcNode.downstream.includes(e.target)) {
        srcNode.downstream.push(e.target);
      }
    }
    if (tgtNode) {
      tgtNode.upstream = tgtNode.upstream || [];
      if (!tgtNode.upstream.includes(e.source)) {
        tgtNode.upstream.push(e.source);
      }
    }
  }

  const nodesByLayer: Record<GraphNodeLayer, number> = {
    product: 0,
    requirement: 0,
    architecture: 0,
    test: 0,
  };

  let conformingCount = 0;
  let issueCount = 0;

  const elements: CytoscapeElement[] = [];

  for (const n of nodeMap.values()) {
    nodesByLayer[n.layer] = (nodesByLayer[n.layer] || 0) + 1;
    if (n.status === 'COMPLIANT' || n.status === 'CONFORME') {
      conformingCount++;
    } else {
      issueCount++;
    }
    elements.push({
      group: 'nodes',
      data: n,
      classes: `layer-${n.layer} type-${n.type} status-${n.status.toLowerCase()}`,
    });
  }

  for (const e of edges) {
    elements.push({
      group: 'edges',
      data: e,
      classes: `relation-${e.relation} status-${e.status?.toLowerCase() || 'compliant'}`,
    });
  }

  return { elements, nodesByLayer, conformingCount, issueCount };
}

/**
 * Loads historical KPI records from reports/releases/ directory.
 */
export function collectHistoricalKpis(rootDir: string): DashboardHistoricalKpi[] {
  const releasesDir = path.join(rootDir, 'reports', 'releases');
  const items: DashboardHistoricalKpi[] = [];

  if (fs.existsSync(releasesDir)) {
    try {
      const files = fs.readdirSync(releasesDir).filter((f) => f.endsWith('.kpis.json'));
      for (const file of files) {
        const fullPath = path.join(releasesDir, file);
        const content = fs.readFileSync(fullPath, 'utf-8');
        const report = JSON.parse(content) as ReleaseKpiReport;
        items.push({
          id: report.releaseBranch,
          label: report.releaseBranch,
          timestamp: report.generatedAt,
          kloc: report.totalKloc,
          commits: report.totalCommits,
          bugs: report.totalBugs,
          defectDensity: report.globalDefectDensity,
          reworkPercent: report.reworkTimePercent,
          costUsd: report.totalCostUsd,
        });
      }
    } catch {
      // Ignore unparseable historical records
    }
  }

  // Sort by timestamp
  return items.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
}

/**
 * Collects complete project metrics for dashboard tabs.
 */
export function collectDashboardMetrics(rootDir: string) {
  const gate = verifyQualityGate({ rootDir });
  const gov = verifyTasksGovernance({ rootDir });
  const cov = verifyTestingCoverage({ rootDir });
  const trace = verifyTraceability({ rootDir });
  const manuals = verifyManuals({ rootDir });
  const history = collectHistoricalKpis(rootDir);

  let activePrKpi = null;
  let activeBranch = 'HEAD';
  try {
    try {
      activeBranch = execFileSync('git', ['rev-parse', '--abbrev-ref', 'HEAD'], {
        cwd: rootDir,
        encoding: 'utf-8',
        stdio: ['pipe', 'pipe', 'pipe'],
      }).trim();
    } catch {
      activeBranch = 'HEAD';
    }

    const isDefaultBranch = activeBranch === 'main' || activeBranch === 'master';
    if (isDefaultBranch) {
      let base = 'HEAD~20';
      try {
        const count = parseInt(
          execFileSync('git', ['rev-list', '--count', 'HEAD'], {
            cwd: rootDir,
            encoding: 'utf-8',
            stdio: ['pipe', 'pipe', 'pipe'],
          }).trim(),
          10
        );
        if (count <= 20) {
          const rootCommit = execFileSync('git', ['rev-list', '--max-parents=0', 'HEAD'], {
            cwd: rootDir,
            encoding: 'utf-8',
            stdio: ['pipe', 'pipe', 'pipe'],
          }).trim().split('\n')[0];
          base = rootCommit;
        }
      } catch {
        base = 'HEAD~1';
      }
      activePrKpi = aggregatePrKpis(base, 'HEAD', { cwd: rootDir });
    } else {
      activePrKpi = aggregatePrKpis('main', 'HEAD', { cwd: rootDir });
      if (activePrKpi.totalCommits === 0) {
        try {
          activePrKpi = aggregatePrKpis('HEAD~1', 'HEAD', { cwd: rootDir });
        } catch {
          // Keep 0 commits if unable
        }
      }
    }
  } catch {
    // Graceful fallback if git range is unavailable
  }

  const codeCoverage = readCodeCoverageSummary(rootDir);

  return {
    gate,
    gov,
    cov,
    codeCoverage,
    trace,
    manuals,
    history,
    activePrKpi,
    activeBranch,
  };
}

function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function safeJsonForScript(data: unknown): string {
  return JSON.stringify(data)
    .replace(/</g, '\\u003c')
    .replace(/>/g, '\\u003e')
    .replace(/&/g, '\\u0026')
    .replace(/\u2028/g, '\\u2028')
    .replace(/\u2029/g, '\\u2029');
}

function renderAutonomyModeSection(
  mode: string,
  statusIcon: string,
  count: number,
  roleDescription: string,
  allTasks: TaskSummary[] = []
): string {
  const modeTasks = (allTasks || []).filter(
    (t) => (t.task?.autonomyMode || '').toUpperCase() === mode
  );
  const openCount = modeTasks.filter(
    (t) => (t.task?.status || '').toUpperCase() !== 'COMPLETED'
  ).length;
  const closedCount = modeTasks.filter(
    (t) => (t.task?.status || '').toUpperCase() === 'COMPLETED'
  ).length;

  return `
    <tr class="mode-row" onclick="toggleAutonomyTasks('${mode}')" title="Haz clic para desplegar u ocultar las tareas ${mode}">
      <td>
        <span class="accordion-indicator" id="toggle-icon-${mode}">▶</span>
        <code>${mode}</code>
        <span style="font-size: 0.72rem; color: var(--accent-cyan); margin-left: 6px;">(Ver tareas ▼)</span>
      </td>
      <td>${statusIcon}</td>
      <td><strong>${count}</strong></td>
      <td>${roleDescription}</td>
    </tr>
    <tr id="tasks-row-${mode}" class="autonomy-tasks-panel" style="display: none;">
      <td colspan="4">
        <div class="autonomy-tasks-container">
          <div class="autonomy-tasks-header">
            <div class="autonomy-tasks-title">
              <span>📋 Tareas <code>${mode}</code></span>
              <span class="badge" style="background:#334155;">Total: ${modeTasks.length}</span>
            </div>
            <div class="filter-btn-group">
              <span style="font-size: 0.75rem; color: var(--text-muted); font-weight: 600;">Filtrar:</span>
              <button type="button" class="filter-btn active" id="btn-filter-${mode}-all" onclick="filterAutonomyTasks('${mode}', 'all', event)">Todas (${modeTasks.length})</button>
              <button type="button" class="filter-btn" id="btn-filter-${mode}-open" onclick="filterAutonomyTasks('${mode}', 'open', event)">Abiertas (${openCount})</button>
              <button type="button" class="filter-btn" id="btn-filter-${mode}-closed" onclick="filterAutonomyTasks('${mode}', 'closed', event)">Cerradas (${closedCount})</button>
            </div>
          </div>
          ${modeTasks.length === 0 ? `
          <div style="color: var(--text-muted); font-size: 0.8rem; padding: 10px 0; font-style: italic;">
            No hay tareas registradas con modo <code>${mode}</code>.
          </div>
          ` : `
          <div id="tasks-empty-${mode}" style="display: none; color: var(--text-muted); font-size: 0.8rem; padding: 10px 0; font-style: italic;">
            No hay tareas en el filtro seleccionado.
          </div>
          <table class="sub-data-table" id="tasks-table-${mode}">
            <thead>
              <tr>
                <th style="width: 105px;">ID Tarea</th>
                <th>Título de la Tarea</th>
                <th style="width: 160px;">Estado</th>
                <th style="width: 130px;">Asignada a</th>
                <th>Verificación</th>
                <th style="width: 200px;">Fichero .md</th>
              </tr>
            </thead>
            <tbody>
              ${modeTasks.map((t) => {
                const cleanPath = (t.file || '').replace(/\\/g, '/').replace(/^\.\//, '');
                const rawStatus = (t.task?.status || 'PENDING').toUpperCase();
                const isClosed = rawStatus === 'COMPLETED';
                const isOpen = !isClosed;
                let badgeClass = 'badge-amber';
                let badgeText = `${rawStatus} (Abierta)`;
                if (rawStatus === 'COMPLETED') {
                  badgeClass = 'badge-green';
                  badgeText = 'COMPLETED (Cerrada)';
                } else if (rawStatus === 'IN_PROGRESS') {
                  badgeClass = 'badge-blue';
                  badgeText = 'IN_PROGRESS (Abierta)';
                } else if (rawStatus === 'BLOCKED') {
                  badgeClass = 'badge-rose';
                  badgeText = 'BLOCKED (Abierta)';
                }
                const criteria = t.task?.verification?.criteria || 'N/A';
                const criteriaShort = criteria.length > 45 ? criteria.substring(0, 42) + '...' : criteria;
                const pathParts = cleanPath.split('/');
                const shortFile = pathParts.length > 2 ? pathParts.slice(-2).join('/') : cleanPath;

                const globalIndex = allTasks.indexOf(t);
                return `
                <tr class="task-row task-item task-item-${isOpen ? 'open' : 'closed'}" onclick="showTaskSidebar(${globalIndex})" title="Ver información de ${escapeHtml(t.task?.id || 'la tarea')}">
                  <td>
                    <strong style="color: var(--accent-cyan); font-family: monospace;"><code>${escapeHtml(t.task?.id || 'TSK-UNKNOWN')}</code></strong>
                  </td>
                  <td>
                    <span style="color: var(--text-main); font-weight: 500;">${escapeHtml(t.task?.title || 'Untitled task')}</span>
                  </td>
                  <td>
                    <span class="badge ${badgeClass}">${escapeHtml(badgeText)}</span>
                  </td>
                  <td>
                    <code>${escapeHtml(t.task?.assignedTo || 'agent-developer')}</code>
                  </td>
                  <td>
                    <code style="font-size: 0.72rem; color: #cbd5e1;" title="${escapeHtml(criteria)}">${escapeHtml(criteriaShort)}</code>
                  </td>
                  <td>
                    <code style="color: var(--text-muted); font-size: 0.75rem;">${escapeHtml(shortFile)}</code>
                  </td>
                </tr>
                `;
              }).join('')}
            </tbody>
          </table>
          `}
        </div>
      </td>
    </tr>
  `;
}

function renderManualsTab(manuals: ManualsVerificationResult): string {
  const c = manuals.coverage;
  const badgeClass =
    manuals.status === 'PASSED' ? 'badge-green' : manuals.status === 'WARNING' ? 'badge-amber' : 'badge-rose';
  const findings = [...manuals.violations, ...manuals.warnings];
  const allManuals = [...manuals.userManuals, ...manuals.productionManuals];

  const findingsHtml =
    findings.length === 0
      ? '<p style="color: var(--accent-emerald); font-size: 0.85rem;">✔ Todos los Journeys, Use Cases, Componentes y Enclaves activos están cubiertos por los manuales.</p>'
      : `<ul style="font-size: 0.82rem; color: #fbbf24; padding-left: 18px; display: flex; flex-direction: column; gap: 4px;">${findings
          .map((f) => `<li>${escapeHtml(f)}</li>`)
          .join('')}</ul>`;

  const rowsHtml =
    allManuals.length === 0
      ? '<tr><td colspan="6" style="color: var(--text-muted);">No hay manuales MAN-USER-* / MAN-PROD-* en <code>manuals/</code>.</td></tr>'
      : allManuals
          .map(
            (m) => `
            <tr onclick="showManual('${escapeHtml(m.id)}')" style="cursor: pointer;">
              <td><strong><code>${escapeHtml(m.id)}</code></strong></td>
              <td>${m.type === 'user-manual' ? '👤 Usuario' : '🛠️ Producción'}</td>
              <td>${escapeHtml(m.title)}</td>
              <td><code>${escapeHtml(m.appliesToVersion)}</code></td>
              <td><span class="badge ${m.status === 'active' ? 'badge-green' : 'badge-amber'}">${escapeHtml(m.status)}</span></td>
              <td><code>${escapeHtml(m.filePath)}</code></td>
            </tr>`
          )
          .join('');

  return `
        <h2>Operational Manuals (User &amp; Production)</h2>
        <p style="font-size: 0.8rem; color: var(--text-muted);">
          Modo de cumplimiento: <span class="badge ${badgeClass}">${manuals.status}</span>
          <code>${manuals.enforcementMode}</code> &middot; rama <code>${escapeHtml(manuals.branch)}</code> &middot; perfil <code>${manuals.profile}</code>.
          Avisos en desarrollo diario; bloqueante en <code>release/*</code> o perfil <code>critical</code>.
        </p>
        <div class="grid-cards">
          <div class="metric-card">
            <span class="title">Cobertura Manual de Usuario</span>
            <span class="value">${c.userCoveragePct}%</span>
            <span class="subtitle">${c.coveredJourneys}/${c.totalJourneys} JRN &middot; ${c.coveredUseCases}/${c.totalUseCases} UC</span>
          </div>
          <div class="metric-card">
            <span class="title">Cobertura Manual de Producción</span>
            <span class="value">${c.productionCoveragePct}%</span>
            <span class="subtitle">${c.coveredComponents}/${c.totalComponents} CMP &middot; ${c.coveredEnclaves}/${c.totalEnclaves} SEC-ENC</span>
          </div>
          <div class="metric-card">
            <span class="title">Manuales Registrados</span>
            <span class="value">${allManuals.length}</span>
            <span class="subtitle">${manuals.userManuals.length} MAN-USER &middot; ${manuals.productionManuals.length} MAN-PROD</span>
          </div>
        </div>
        <div class="chart-container">
          <h3>Hallazgos de Cobertura</h3>
          ${findingsHtml}
        </div>
        <table class="data-table">
          <thead>
            <tr><th>ID</th><th>Tipo</th><th>Título</th><th>Aplica a</th><th>Estado</th><th>Fichero</th></tr>
          </thead>
          <tbody>${rowsHtml}</tbody>
        </table>
        <div class="chart-container" id="manual-viewer-container" style="display: none;">
          <h3 id="manual-viewer-title"></h3>
          <div id="manual-viewer" style="font-size: 0.82rem; line-height: 1.5; color: #cbd5e1;"></div>
        </div>`;
}

